(()=>{let e=document.querySelector(".modal_success"),t=document.getElementById("success");document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{e.classList.add("show"),e.scrollIntoView({behavior:"smooth"}),t.textContent="You are now being redirected to your dashboard"},7e3)}),setTimeout(()=>{setTimeout(()=>{e.classList.remove("show"),location.href="Dashboard.html"},7e3)},9e3)})();